import { defineConfig } from "@playwright/test";

const executablePath = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE;

/**
 * One spec group is not a regression test and must not fail a push:
 *
 *   *-captures.spec.ts  write screenshots into gitignored artifacts/ so the gallery
 *                       can be regenerated by hand. Nothing is compared; running
 *                       them in CI only produces files nobody keeps.
 *
 * editor-task5-performance.spec.ts has its own production-preview config
 * (playwright.performance.config.ts), because a development React build's
 * StrictMode/profiling renders are not the product's commit cost. Keeping it out
 * of this config also keeps its one-worker run from competing with these specs
 * for CPU.
 *
 * TWIN_E2E_CI=1 turns the capture writers off. CI runs two independent tests at a
 * time in one job; a local `npm run test:e2e` keeps one worker.
 */
const ci = process.env.TWIN_E2E_CI === "1";
const ignored = ["**/editor-task5-performance.spec.ts", ...(ci ? ["**/*-captures.spec.ts"] : [])];

export default defineConfig({
  testDir: "./e2e",
  testIgnore: ignored,
  timeout: 30_000,
  fullyParallel: true,
  workers: ci ? 2 : 1,
  reporter: "list",
  use: {
    baseURL: "http://127.0.0.1:5173",
    viewport: { width: 1280, height: 1000 },
    trace: "retain-on-failure",
    launchOptions: executablePath ? { executablePath } : {},
  },
  webServer: {
    command: "npm run dev -- --host 127.0.0.1 --port 5173",
    url: "http://127.0.0.1:5173",
    reuseExistingServer: true,
    timeout: 120_000,
  },
});
